-- CONDITIONS (4 rows; Greywake-specific)
INSERT INTO "public"."condition" ("condition_id", "name", "scope", "source_pack", "abbreviation", "ui_glyph", "ui_category", "stackable", "level_based", "max_level", "duration_types_allowed", "effect_rules", "removal_methods", "schema_version")
SELECT
  x->>'condition_id',
  x->>'name',
  x->>'scope',
  x->>'source_pack',
  x->>'abbreviation',
  x->>'ui_glyph',
  x->>'ui_category',
  (x->>'stackable')::boolean,
  (x->>'level_based')::boolean,
  (x->>'max_level')::int,
  (x->'duration_types_allowed'),
  x->>'effect_rules',
  (x->'removal_methods'),
  'v0.8'
FROM jsonb_array_elements('[{"condition_id":"salt_rimed","name":"Salt-Rimed","scope":"regional","source_pack":"greywake_conditions_v1","abbreviation":"SLT","ui_glyph":"salt-crystal-band","ui_category":"metaphysical","stackable":false,"level_based":true,"max_level":2,"duration_types_allowed":["n_scenes","until_long_rest","until_canon_event"],"effect_rules":"Level 1 (light): -1 to DEX checks involving fine manipulation; visible salt-crystal-band on hands and lips; faintly tide-bloom in Drowned Church presence. Level 2 (heavy): -1 to DEX checks AND -1 to CHA checks against non-Greywake NPCs (they read you as ''one of the salt''); cannot be removed by ordinary washing; Drowned Church faction stance shifts toward favorable by +1 if heavy-rimed witnessed in cathedral. Both levels: practicing water flows toward the rimed body if within 5 ft; minor narrative effect but witnessed by NPCs.","removal_methods":["long rest in fresh (non-salt) water","Purgative Tincture (alchemy slice recipe)","Imposed Unname spell variant (not slice-available)","Drowned Church absolution rite (Faith:Umberlee >= 4 required to be offered)"]},{"condition_id":"recognized_by_not_yet_named","name":"Recognized by Not-Yet-Named","scope":"regional","source_pack":"greywake_conditions_v1","abbreviation":"RNN","ui_glyph":"tide-bloom-eye-half-open","ui_category":"metaphysical","stackable":false,"level_based":false,"duration_types_allowed":["until_canon_event","permanent"],"effect_rules":"The Unnamed has noticed the bearer. While active: +1 Notice from The Unnamed per cast of any Imposed-school spell; -1 to Stealth in metaphysical perception domains (the bearer is faintly visible to anything that perceives through Authority-pressure); +1 to Insight checks involving naming, oath-keeping, or word-power; one canon-event opportunity per long rest where the World Director may surface a ''name proposal'' (an NPC or environment offers a tentative name for the Unnamed-as-noticed-you; declining holds the condition; accepting may resolve it but commits a contradiction ledger entry).","removal_methods":["canon-event resolution (one of the name-proposals accepted; contradiction ledger seeded)","deicide of The Unnamed (extreme; substrate_practicing_word re-exposes)","Imposed Unrecord spell targeting the perception-event that started recognition (DC 18)"]},{"condition_id":"debt_marked","name":"Debt-Marked","scope":"regional","source_pack":"greywake_conditions_v1","abbreviation":"DBT","ui_glyph":"drowned-coin-stamp","ui_category":"social_legal","stackable":false,"level_based":false,"duration_types_allowed":["until_canon_event"],"effect_rules":"The bearer carries an unresolved debt to a named creditor (faction or NPC). Debt meter floor for this character is the debt value or 2, whichever is greater. While active: -2 to Persuasion checks vs the creditor or their representatives; +1 to Insight checks specifically about the creditor''s interests; Tide League and Bell Court NPCs can read the debt mark on sight (it appears as a faint stamp on the bearer''s clothing, brass-tinted); creditor may dispatch a collector NPC if debt exceeds 6 or in-world time elapses without payment. Bearer may transfer debt via canon-event (with creditor consent) or pay it off (which removes the condition).","removal_methods":["pay the debt in full (creditor receives commensurate value; state_diff commits)","creditor''s death or dissolution (debt void; contradiction ledger ''unmade_event'' kind seeded)","transfer to another bearer via consenting canon-event"]},{"condition_id":"bell_marked","name":"Bell-Marked","scope":"regional","source_pack":"greywake_conditions_v1","abbreviation":"BLM","ui_glyph":"single-bell-strike-glyph","ui_category":"social_legal","stackable":false,"level_based":false,"duration_types_allowed":["n_scenes","until_long_rest","until_canon_event"],"effect_rules":"The Bell Court has rung the bell against the bearer (formally or by accidental association during an off-hour strike). While active: -1 to all CHA checks vs Bell Court NPCs; +1 to checks involving witnesses (the bell-mark counts as a witness in legal proceedings, sometimes for the bearer, sometimes against); Bell Court visitor ledger entries about the bearer are treated as canonical_observation rather than rumor; the mark is visible to Bell-Magistrate Orro and his deputies. Three accumulated bell-marks in a campaign (path:law domain weight >= 3) escalates to permanent Bell-Marked status with attendant legal consequences.","removal_methods":["Bell Court formal absolution (DC 15 Persuasion or canon-event resolving the underlying charge)","duration expiry (most bell-marks expire over n_scenes or until_long_rest)","Bell-Marked Charm attunement (slice item) provides partial mitigation: -1 to penalty severity while attuned"]}]'::jsonb) AS x
ON CONFLICT ("condition_id") DO NOTHING;

-- LITANIES (20 rows; Drowned Church liturgical content)
INSERT INTO "public"."litany" ("litany_id", "title", "text_body", "mechanical_effect", "voice_register", "rite_kind", "faction_origin", "first_heard_default_npc", "origin_institution", "canonical_use", "tags", "tone_tags", "schema_version")
SELECT
  x->>'litany_id',
  x->>'title',
  x->>'text_body',
  x->>'mechanical_effect',
  x->>'voice_register',
  x->>'rite_kind',
  x->>'faction_origin',
  x->>'first_heard_default_npc',
  x->>'origin_institution',
  x->>'canonical_use',
  (x->'tags'),
  (x->'tone_tags'),
  'v0.8'
FROM jsonb_array_elements('[{"litany_id":"salt_litany_of_three_becoming","title":"The Salt Litany of Three Becoming","text_body":"three becomes one becomes none / and what was three remembers being one / and what was one remembers being three / and the witness keeps the count","mechanical_effect":"On full hearing: +1 path:silence credit; +1 Notice from The Unnamed; substrate_practicing_word exposure event seeded for listener.","voice_register":"unspecified","rite_kind":"Recited at the salt vigil; spoken by Marrow-Saints when the ","faction_origin":"","first_heard_default_npc":"npc_marrow_saint_ilyra","origin_institution":"drowned_church_greywake","canonical_use":"Recited at the salt vigil; spoken by Marrow-Saints when the fountain answers. Hearing the full four lines exposes substrate_practicing_word for the listener for 1d4 in-world days.","tags":[],"tone_tags":["counting","becoming","witness","drowned_church"],"schema_version":"v1"},{"litany_id":"wave_counters_count","title":"The Wave-Counter''s Count","text_body":"one for the drowned / one for the named / one for the witness who keeps the count / and one we do not say","mechanical_effect":"On full hearing: +1 path:law credit; Helm Faith Meter +1 if listener is on civic business.","voice_register":"unspecified","rite_kind":"Opens Bell Court hearings concerning drowning deaths. The fo","faction_origin":"","first_heard_default_npc":"npc_bell_magistrate_orro","origin_institution":"civic_bell_court_greywake","canonical_use":"Opens Bell Court hearings concerning drowning deaths. The fourth line is whispered, not spoken; whispering it aloud is a Court taboo (taboo_amend_ledger-adjacent).","tags":[],"tone_tags":["counting","law","drowned","bell_court","the_unspoken_fourth"],"schema_version":"v1"},{"litany_id":"what_the_fountain_refuses","title":"What the Fountain Refuses","text_body":"what is given cannot return / unless the giver is unmade also / and what is unmade is not given but remembered / and what is remembered cannot be given again","mechanical_effect":"On full hearing: +1 path:silence; clarity +1 on first hearing only; subsequent hearings have no effect.","voice_register":"unspecified","rite_kind":"Whispered by the Listening Child at the dry fountain. Crucia","faction_origin":"","first_heard_default_npc":"npc_the_listening_child","origin_institution":"drowned_church_greywake","canonical_use":"Whispered by the Listening Child at the dry fountain. Crucial to understanding the slice''s central crisis (the fountain leaking upward = something is being unmade and remembered, not given back).","tags":[],"tone_tags":["fountain","unmade","inversion","drowned_church","listening_child"],"schema_version":"v1"},{"litany_id":"practicing_word","title":"Practicing Word","text_body":"first you ask / second you call / third the world answers in your voice / and the fourth answer is your own name returning","mechanical_effect":"On full hearing near practicing water: substrate_practicing_word exposure event committed via state_diff; Authority +0.5 weight toward next canon-progression; Notice +1 from The Unnamed.","voice_register":"unspecified","rite_kind":"Spoken (or stuttered) by The Butcher Who Repeats during the ","faction_origin":"","first_heard_default_npc":"npc_the_butcher_who_repeats","origin_institution":"drowned_church_greywake","canonical_use":"Spoken (or stuttered) by The Butcher Who Repeats during the repetition. The litany is the substrate_practicing_word pattern in litany form. Hearing all four lines while in the presence of practicing water binds the speaker into the substrate''s witness chain.","tags":[],"tone_tags":["practicing","name","self_return","butcher","drowned_church"],"schema_version":"v1"},{"litany_id":"litany_of_the_marrow_saints_hand","title":"Litany of the Marrow-Saint''s Hand","text_body":"this hand has been salt / this hand has been bone / this hand has held a child to the water / this hand has held the water to a child / and the hand knows which it was","mechanical_effect":"On full hearing: enables the next healing-ritual or recovery-rite cast by a Marrow-Saint to operate at +1 effective level; +1 path:mercy credit on the listener if witnessed.","voice_register":"unspecified","rite_kind":"Spoken by Marrow-Saints before laying hands on a body (livin","faction_origin":"","first_heard_default_npc":"npc_marrow_saint_ilyra","origin_institution":"drowned_church_greywake","canonical_use":"Spoken by Marrow-Saints before laying hands on a body (living or drowned). Required by Drowned Church doctrine before any healing or recovery ritual. Refusal to speak it before laying hands is a doctrine_doc_salt_first_witness violation.","tags":[],"tone_tags":["hand","memory","drowned_church","healing"],"schema_version":"v1"},{"litany_id":"salt_vigil_round","title":"The Salt-Vigil Round","text_body":"we keep the salt because the salt kept us / we keep the watch because the watch keeps the salt / we keep the name because the name keeps the watch / and when one of three breaks, the other two carry","mechanical_effect":"Witnessing a complete round (3+ singers) grants Inspiration token to one listener at GM/World Director discretion; +1 Drowned Church faction reputation if listener participates.","voice_register":"unspecified","rite_kind":"Sung in round (overlapping voices) at the weekly salt vigil.","faction_origin":"","first_heard_default_npc":"npc_marrow_saint_ilyra","origin_institution":"drowned_church_greywake","canonical_use":"Sung in round (overlapping voices) at the weekly salt vigil. The round structure means each line is held by at least two singers at any moment. If a singer drops, the litany continues. The doctrinal point is that Greywake''s faith does not depend on any single voice.","tags":[],"tone_tags":["vigil","round","redundancy","drowned_church"],"schema_version":"v1"},{"litany_id":"listing_of_the_names_not_spoken","title":"The Listing of the Names Not Spoken","text_body":"the name we do not say of the Mother / the name we do not say of the Practicing Voice / the name we do not say of the Child Who Listens / the name we do not say of the one who will come after the Child / and the name we do not say because we do not yet know it","mechanical_effect":"On full hearing: substrate_naming_taboo exposure event seeded for the listener for 1 in-world day; Authority +0.3 weight toward next canon-progression; +1 path:silence.","voice_register":"unspecified","rite_kind":"Recited at the annual remembrance vigil and at canon-events ","faction_origin":"","first_heard_default_npc":"npc_marrow_saint_ilyra","origin_institution":"drowned_church_greywake","canonical_use":"Recited at the annual remembrance vigil and at canon-events of significance ≥ 4. The fifth line is the doctrinally crucial one — the Drowned Church explicitly leaves space for unnamed-as-yet divinities. This is how the Church accommodates The Unnamed without doctrinal crisis.","tags":[],"tone_tags":["naming_taboo","drowned_church","the_unnamed","doctrinal_space"],"schema_version":"v1"},{"litany_id":"bell_and_inkwell","title":"Bell-and-Inkwell","text_body":"the bell strikes at the hour / the inkwell sits at the bench / between the bell and the inkwell the Court is the Court / and outside the bell and the inkwell the Court is nothing","mechanical_effect":"Players who hear this litany at session opening gain legal-fiction knowledge: actions outside Court-time and Court-place are not Court-jurisdictional. May open new dialogue surfaces with NPCs who care about this distinction (lawyers, smugglers, escaped debtors).","voice_register":"unspecified","rite_kind":"Daily opening of Bell Court sessions. Defines the Court''s ju","faction_origin":"","first_heard_default_npc":"npc_bell_magistrate_orro","origin_institution":"civic_bell_court_greywake","canonical_use":"Daily opening of Bell Court sessions. Defines the Court''s jurisdiction as temporal and spatial: only between the bell-strike and the inkwell does Court law apply. Outside those bounds, Court has no claim. (This is the Court''s own self-limiting doctrine; it is also why street-level Greywake events often go uncounted.)","tags":[],"tone_tags":["bell_court","jurisdiction","law","opening"],"schema_version":"v1"},{"litany_id":"witness_clause","title":"The Witness Clause","text_body":"the witness names what the witness saw / the witness does not name what the witness believes / the witness does not name what the witness wishes / and what the witness wished is for the witness alone","mechanical_effect":"If sworn before testifying, the witness''s testimony is treated as canonical observation (event.severity may be elevated); refusing to swear leaves testimony as belief (rumor-track instead of canon-track).","voice_register":"unspecified","rite_kind":"Spoken by a witness before testimony in Bell Court. The lega","faction_origin":"","first_heard_default_npc":"npc_bell_magistrate_orro","origin_institution":"civic_bell_court_greywake","canonical_use":"Spoken by a witness before testimony in Bell Court. The legal formula constrains testimony to observation, excluding inference and desire. The fourth line is a small mercy — the witness keeps their interior.","tags":[],"tone_tags":["bell_court","law","testimony","interiority"],"schema_version":"v1"},{"litany_id":"what_the_ledger_records","title":"What the Ledger Records","text_body":"what the ledger records is what was / what the ledger does not record is not / what the ledger misspells was misspelled / and what the ledger crossed out was crossed out, not removed","mechanical_effect":"On full hearing: listeners who attempt to amend the visitor ledger receive Bell Court hostile-action prompt with +1 severity. Crossed-out names become legible to the listener for 1 in-world day (they can read what was ''removed'').","voice_register":"unspecified","rite_kind":"Recited by Bell Court scribes when sealing the daily ledger.","faction_origin":"","first_heard_default_npc":"npc_bell_magistrate_orro","origin_institution":"civic_bell_court_greywake","canonical_use":"Recited by Bell Court scribes when sealing the daily ledger. The doctrinal force: the Court treats the visitor ledger as canonically authoritative even where it errs. The fourth line is what permits the contradiction ledger to coexist with civic law: a cross-out is itself a record.","tags":[],"tone_tags":["bell_court","ledger","memory_vs_record","contradiction"],"schema_version":"v1"},{"litany_id":"salt_holds_scrip_promises","title":"Salt Holds, Scrip Promises","text_body":"salt holds where the day held / scrip promises what tomorrow may hold / the third speculation is the price / and the price is the salt and the promise together","mechanical_effect":"If the player hears this litany on the day they trade scrip, the salt-scrip exchange rate is shown to them transparently at full precision (not bucketed). Otherwise scrip values are shown bucketed.","voice_register":"unspecified","rite_kind":"Opening of Tide League trading day. Recited by the senior Br","faction_origin":"","first_heard_default_npc":"npc_venn_hook","origin_institution":"merchant_tide_league_greywake","canonical_use":"Opening of Tide League trading day. Recited by the senior Broker present. The litany names the League''s pricing principle: the canonical price is set by the third speculation (per doc_third_speculation_is_canon), and that price is the combined value of salt-held and scrip-promised.","tags":[],"tone_tags":["tide_league","trade","scrip","speculation"],"schema_version":"v1"},{"litany_id":"the_third_speculation","title":"The Third Speculation","text_body":"the first speculation is a hope / the second speculation is a counter / the third speculation is the price / and the fourth speculation is the lie that breaks the market","mechanical_effect":"If a player publicly names four or more speculations on Tide League goods within a single scene, salt-scrip volatility_modifier increases by 0.15 (state_diff committed by State Manager). The litany is the Court''s-eye-view warning of this consequence.","voice_register":"unspecified","rite_kind":"Closing of Tide League trading day. Recited as a warning to ","faction_origin":"","first_heard_default_npc":"npc_venn_hook","origin_institution":"merchant_tide_league_greywake","canonical_use":"Closing of Tide League trading day. Recited as a warning to apprentices: the canonical price is the third, not the fourth. Speculation beyond the third is doctrinally forbidden (taboo_speculate_after_third). The litany makes the rule remembered.","tags":[],"tone_tags":["tide_league","speculation","market_warning","the_fourth_lie"],"schema_version":"v1"},{"litany_id":"litany_what_remains_after_naming","faction_origin":"fac_drowned_church","rite_kind":"vigil_of_listening","title":"What Remains After Naming","text_body":"what is named does not always remain / what is unnamed has been remaining always","voice_register":"marrow_saint_intoned","mechanical_effect":{"trigger_conditions":["spoken_during_vigil_of_listening","spoken_at_dry_fountain"],"faith_delta":{"deity_id":"deity_the_unnamed","amount":1},"path_delta":{"axis":"listener","amount":1},"substrate_exposure":"substrate_naming_taboo"},"tags":["slice_eligible","vigil","the_unnamed"],"schema_version":"v2"},{"litany_id":"litany_clerks_compline","faction_origin":"fac_civic_bell_court","rite_kind":"what_the_ledger_records","title":"Clerk''s Compline","text_body":"we close at the seventh bell / what was entered remains entered / what was struck has the weight of the struck","voice_register":"bell_court_clerk_recitative","mechanical_effect":{"trigger_conditions":["spoken_at_bell_court_precinct","civic_day_ending"],"faction_awareness_delta":{"faction_id":"fac_civic_bell_court","trust":1}},"tags":["slice_eligible","civic","closing"],"schema_version":"v2"},{"litany_id":"litany_witness_clause_short","faction_origin":"fac_civic_bell_court","rite_kind":"witness_clause","title":"Witness Clause (short form)","text_body":"this witness records / this witness does not embellish / this witness''s record is admissible","voice_register":"bell_court_self_swearing","mechanical_effect":{"trigger_conditions":["spoken_before_giving_testimony","player_acts_as_witness"],"advantage_on_next_check":"presence_for_civic_credibility","ledger_entry_made":true},"tags":["slice_eligible","civic","testimony"],"schema_version":"v2"},{"litany_id":"litany_what_the_warrant_does_not_say","faction_origin":"fac_civic_bell_court","rite_kind":"what_the_ledger_records","title":"What the Warrant Does Not Say","text_body":"the warrant names what it names / what the warrant does not name is not therefore innocent / it is the warrant that is silent","voice_register":"orro_off_record","mechanical_effect":{"trigger_conditions":["spoken_when_warrant_filed","player_is_subject_of_warrant"],"investigation_advantage":true,"contradiction_ledger_entry_kind":"warrant_silence"},"tags":["slice_eligible","civic","off_record"],"schema_version":"v2"},{"litany_id":"litany_third_speculation_close","faction_origin":"fac_merchant_tide_league","rite_kind":"third_speculation","title":"Third Speculation (closing)","text_body":"the third speculation closes at twenty-five / the third speculation has always closed at twenty-five / what closes at twenty-five does not deepen the market","voice_register":"broker_recitative","mechanical_effect":{"trigger_conditions":["spoken_at_market_close","scrip_speculation_within_25_percent"],"faction_awareness_delta":{"faction_id":"fac_merchant_tide_league","trust":1},"scrip_cap_enforcement":"soft_25_pct"},"tags":["slice_eligible","economic","cap_enforcement"],"schema_version":"v2"},{"litany_id":"litany_courier_oath","faction_origin":"fac_merchant_tide_league","rite_kind":"salt_scrip_oath","title":"Courier''s Oath","text_body":"the envelope is sealed / what is sealed will be moved as sealed / the moving is what the league pays for","voice_register":"broker_to_new_courier","mechanical_effect":{"trigger_conditions":["spoken_at_acceptance_of_courier_assignment"],"binding_oath":"tide_league_sealed_transit","violation_consequence":"scrip_blacklist + faction_trust -3"},"tags":["slice_eligible","economic","binding_oath"],"schema_version":"v2"},{"litany_id":"litany_audit_acceptance","faction_origin":"fac_merchant_tide_league","rite_kind":"salt_scrip_oath","title":"Audit Acceptance","text_body":"the records are open / what the records show is what the league shows / what the league does not show is not the records'' fault","voice_register":"broker_during_bell_court_audit","mechanical_effect":{"trigger_conditions":["spoken_at_start_of_bell_court_audit","tide_league_member_speaking"],"audit_intensity":"reduced_to_low"},"tags":["slice_eligible","economic","audit"],"schema_version":"v2"},{"litany_id":"litany_the_weighing","faction_origin":"fac_merchant_tide_league","rite_kind":"salt_scrip_oath","title":"The Weighing","text_body":"everything weighs / most things weigh something specific / the broker holds the scale","voice_register":"venn_hook_signature","mechanical_effect":{"trigger_conditions":["spoken_before_a_transaction","broker_present"],"negotiation_advantage":true,"passive_effect":"venn_hook_recognizes_player_as_serious"},"tags":["slice_eligible","economic","venn_signature","broker"],"schema_version":"v2"}]'::jsonb) AS x
ON CONFLICT ("litany_id") DO NOTHING;

-- MARGINALIA (25 rows; Codex marginalia)
INSERT INTO "public"."marginalia" ("marginalia_id", "text", "trigger_kind", "trigger_event_kind", "tone_tags", "schema_version")
SELECT
  x->>'marginalia_id',
  x->>'text',
  x->>'trigger_kind',
  x->>'trigger_event_kind',
  (x->'tone_tags'),
  'v0.8'
FROM jsonb_array_elements('[{"marginalia_id":"marg_fountain_three_drops","text":"Marrow-Saint Ilyra named the salt litany. The fountain answered with three drops above the surface, then stopped.","trigger_kind":"canon_progression_event","trigger_event_kind":"rite","tone_tags":["fountain","litany","drowned_church","answered_event"],"schema_version":"v1"},{"marginalia_id":"marg_scrip_for_unmade_dagger","text":"Venn Hook offered 8 scrip for the dagger you have not made yet. He does not ask whether you have salt-iron. He assumes.","trigger_kind":"canon_progression_event","trigger_event_kind":"social_conflict","tone_tags":["tide_league","speculation","presumption","venn_hook"],"schema_version":"v1"},{"marginalia_id":"marg_misspelled_ledger","text":"Bell-Magistrate Orro recorded your name in the visitor ledger. He misspelled it. The misspelling is the canonical entry.","trigger_kind":"canon_progression_event","trigger_event_kind":"faction_action","tone_tags":["bell_court","ledger","memory_vs_record","name"],"schema_version":"v1"},{"marginalia_id":"marg_three_witnesses_at_fountain","text":"The fountain leaked upward. Three bystanders looked. One was Bell Court; one was Drowned Church; one was you. The Bell Court witness will file a report by night.","trigger_kind":"canon_progression_event","trigger_event_kind":"environment_anomaly","tone_tags":["fountain","witness_count","inversion","consequence_seeded"],"schema_version":"v1"},{"marginalia_id":"marg_charm_spoke_twice","text":"Bell-Marked Charm attuned: salt-immersion ritual completed. Slot 0 bound. The charm spoke twice on the second submersion. You did not understand it.","trigger_kind":"canon_progression_event","trigger_event_kind":"item_event","tone_tags":["attunement","item_soul","drowned_church","not_understood"],"schema_version":"v1"},{"marginalia_id":"marg_listening_child_answered_before","text":"The Listening Child answered a question. You had not yet asked it. The Bell Court scribe nearby did not write it down because no question was on record.","trigger_kind":"canon_progression_event","trigger_event_kind":"npc_speech_anomaly","tone_tags":["listening_child","temporal_inversion","bell_court_blindspot","unrecorded"],"schema_version":"v1"},{"marginalia_id":"marg_butcher_stopped_repeating","text":"The Butcher Who Repeats did not repeat in your presence today. He said one thing once. He looked surprised by the silence after.","trigger_kind":"canon_progression_event","trigger_event_kind":"npc_speech_anomaly","tone_tags":["butcher","anomaly","single_utterance","bond_marker"],"schema_version":"v1"},{"marginalia_id":"marg_scrip_value_shifted","text":"Salt-scrip moved from 0.85 to 0.72 between morning and midday. No one named the cause aloud. The Tide League''s chalkboard does not show the morning value.","trigger_kind":"canon_progression_event","trigger_event_kind":"faction_action","tone_tags":["tide_league","scrip","volatility","erased_evidence"],"schema_version":"v1"},{"marginalia_id":"marg_bell_struck_off_hour","text":"The Bell Court bell struck once outside its recorded hour. The scribes pretended not to hear. The bell does not.","trigger_kind":"canon_progression_event","trigger_event_kind":"environment_anomaly","tone_tags":["bell_court","taboo_violation_off_hour","denial","the_bell_does_not_pretend"],"schema_version":"v1"},{"marginalia_id":"marg_litany_overlapped","text":"Two singers held the third line of the salt-vigil round when the fourth dropped out. The round continued. No one looked at the singer who dropped.","trigger_kind":"canon_progression_event","trigger_event_kind":"rite","tone_tags":["drowned_church","redundancy","the_unobserved_failure","round"],"schema_version":"v1"},{"marginalia_id":"marg_weather_omen_salt_dust","text":"Salt-dust fell south of the market today instead of north. The fishermen noticed; the bookkeepers did not. The fishermen are usually right about this.","trigger_kind":"canon_progression_event","trigger_event_kind":"weather_omen","tone_tags":["weather","salt","professional_knowledge","asymmetric_attention"],"schema_version":"v1"},{"marginalia_id":"marg_canon_progression_held","text":"Authority would have advanced today, except you refused the offered name. Authority does not advance on refusal; the credit is held against the next canon-event you do not refuse.","trigger_kind":"canon_progression_event","trigger_event_kind":"canon_progression_event","tone_tags":["canon_progression","asi_sacrifice_held","refusal","Khojen_path"],"schema_version":"v1"},{"marginalia_id":"marg_canon_progression_authority_5","trigger_kind":"canon_progression_event","trigger_condition":"player.authority >= 5 (first time crossing threshold)","text":"Something in the room — the room itself — adjusts to the weight you have begun to carry. The candles do not flicker. The candles know.","display_context":"player_journal_at_end_of_scene"},{"marginalia_id":"marg_canon_progression_ruin_5","trigger_kind":"canon_progression_event","trigger_condition":"player.ruin >= 5 (first time crossing threshold)","text":"The cuff of the left sleeve has gone the colour the rust would be if rust were warm. The cuff is not rust. The cuff is salt-touched, set into the weave like a stain that has decided.","display_context":"player_journal_at_end_of_scene"},{"marginalia_id":"marg_canon_progression_creation_5","trigger_kind":"canon_progression_event","trigger_condition":"player.creation >= 5 (first time crossing threshold)","text":"A line is drawn on a piece of paper and the paper is not the same paper. The line is also not a line. This is acceptable.","display_context":"player_journal_at_end_of_scene"},{"marginalia_id":"marg_item_bell_marked_charm_first_warm","trigger_kind":"item_event","trigger_condition":"item_bell_marked_charm warms for the first time (proximity to Bell Court ledger entry)","text":"The charm in the pocket — small, brass, salt-stamped — is warm against the thigh. Something has been entered into a ledger somewhere very close.","display_context":"inline_during_scene"},{"marginalia_id":"marg_item_pebble_returns","trigger_kind":"item_event","trigger_condition":"item_listening_childs_pebble returns after intentional drop","text":"The pebble is back in the pocket. The drop did not take. The pebble is not a thing that is lost.","display_context":"inline_during_scene"},{"marginalia_id":"marg_weather_salt_haze_thick","trigger_kind":"weather_omen","trigger_condition":"salt_haze intensity reaches 4+ (slice maximum)","text":"The haze on the market today carries grit that settles on the tongue. The grit tastes like the spoken syllables of someone who has not spoken yet.","display_context":"inline_at_scene_open"},{"marginalia_id":"marg_weather_fountain_silver","trigger_kind":"weather_omen","trigger_condition":"scene at dry fountain + day_phase=evening_silver_reflection","text":"The standing-water that is not standing has caught the late silver light. The fountain is not reflecting. The fountain is being addressed.","display_context":"inline_at_scene_open"},{"marginalia_id":"marg_faction_action_drowned_vigil_observed","trigger_kind":"faction_action","trigger_condition":"fac_drowned_church performs salt_vigil_evening with player observing","text":"The salt-vigil is exactly what was described. Exactness is the unsettling part.","display_context":"player_journal_at_end_of_scene"},{"marginalia_id":"marg_faction_action_bell_court_audit_open","trigger_kind":"faction_action","trigger_condition":"fac_civic_bell_court ledger_audit_open_session with player present","text":"Three clerks at three desks reading three ledgers aloud at three different rates. The reading does not synchronize. It does not need to.","display_context":"player_journal_at_end_of_scene"},{"marginalia_id":"marg_social_conflict_refused_by_marrow_saint","trigger_kind":"social_conflict","trigger_condition":"Marrow-Saint Ilyra refuses to acknowledge player (faith_drowned_church <= -3)","text":"She looked through, not at. The looking-through was deliberate. It is not the same as being unseen.","display_context":"player_journal_at_end_of_scene"},{"marginalia_id":"marg_social_conflict_orro_off_record_offer","trigger_kind":"social_conflict","trigger_condition":"Bell-Magistrate Orro sets inkwell aside (off-record marker)","text":"He set the inkwell down. The conversation is off the record now. The conversation was never going to be on it.","display_context":"inline_during_scene"},{"marginalia_id":"marg_npc_speech_listening_child_quotes","trigger_kind":"npc_speech_anomaly","trigger_condition":"The Listening Child speaks (any utterance)","text":"The child speaks the way one repeats something already said. The thing already said has not yet been said.","display_context":"inline_during_scene"},{"marginalia_id":"marg_npc_speech_butcher_provenance_revealed","trigger_kind":"npc_speech_anomaly","trigger_condition":"Butcher Who Repeats discloses the provenance of the cuts (sec_butcher_contradiction_revealed)","text":"He said it the way one says something for the third time. It was the first time it had been said aloud to anyone.","display_context":"player_journal_at_end_of_scene"}]'::jsonb) AS x
ON CONFLICT ("marginalia_id") DO NOTHING;

-- IMPOSED SPELLS (5 rows; NPC-imposed slice spells incl. harden_contradiction, compose, hear_the_fountain)
INSERT INTO "public"."imposed_spell" ("spell_id", "name", "level", "school", "regional_school_id", "regional_origin_id", "regional_pantheon_alignment", "casting_time", "range", "components", "duration", "classes_allowed", "domain_aligned", "cost_layer", "concentration", "ritual_eligible", "save_type", "attack_kind", "damage_dice", "damage_type", "description_template", "schema_version")
SELECT
  x->>'spell_id',
  x->>'name',
  (x->>'level')::int,
  x->>'school',
  x->>'regional_school_id',
  x->>'regional_origin_id',
  x->>'regional_pantheon_alignment',
  x->>'casting_time',
  x->>'range',
  (x->'components'),
  (x->'duration'),
  (x->'classes_allowed'),
  (x->'domain_aligned'),
  (x->'cost_layer'),
  (x->>'concentration')::boolean,
  (x->>'ritual_eligible')::boolean,
  x->>'save_type',
  x->>'attack_kind',
  x->>'damage_dice',
  x->>'damage_type',
  x->>'description_template',
  'v0.8'
FROM jsonb_array_elements('[{"spell_id":"hear_the_fountain","name":"Hear the Fountain","level":1,"school":"regional","regional_school_id":"greywake_imposed","regional_origin_id":"greywake","regional_pantheon_alignment":"greywake_drowned_church_config","casting_time":"1 action","range":"30 ft","components":{"v":true,"s":true,"m":true,"m_text":"a drop of practicing water or fountain water","m_consumed":true,"m_cost_gp":0},"duration":{"kind":"instant"},"concentration":false,"ritual_eligible":false,"save_type":"wis","attack_kind":null,"damage_dice":null,"damage_type":null,"classes_allowed":["warlock","cleric","druid"],"domain_aligned":["knowledge","trickery"],"cost_layer":{"fatigue":1,"notice":0,"corruption":0,"authority":1,"ruin":0,"creation":0,"scaling_rule":"L1: as listed. Upcast L2+: fatigue +1 per slot level above 1; notice +1 at L3+. Imposed authority cost does not scale (always 1)."},"description_template":"Touching a drop of practicing water or fountain water to the throat or wrist, the caster compels target within 30 ft (WIS save resists) to reveal one belief or one rumor they hold. The target experiences this as remembering something they had forgotten; the rumor or belief is what they would have said if asked, never a hidden truth they did not believe. Target gains awareness that they were the source. Caster takes Fatigue +1, Authority +1 (canon-progression event credit if used to discover a Greywake faction''s plan)."},{"spell_id":"salt_mark","name":"Salt-Mark","level":1,"school":"regional","regional_school_id":"greywake_imposed","regional_origin_id":"greywake","regional_pantheon_alignment":"greywake_drowned_church_config","casting_time":"1 bonus action","range":"touch","components":{"v":true,"s":true,"m":true,"m_text":"a pinch of butcher''s salt or salt-rime","m_consumed":true,"m_cost_gp":0},"duration":{"kind":"n_scenes","n":1},"concentration":false,"ritual_eligible":false,"save_type":null,"attack_kind":null,"damage_dice":null,"damage_type":null,"classes_allowed":["warlock","cleric","druid"],"domain_aligned":["trickery"],"cost_layer":{"fatigue":1,"notice":0,"corruption":0,"authority":1,"ruin":0,"creation":0,"scaling_rule":"L1: as listed. Upcast L2+: target gains bell-marked condition (level 1) instead of salt-rimed; fatigue +1 per slot level above 1; notice +1 at L3+."},"description_template":"Caster touches the target (consenting or grappled) and presses salt into skin or cloth. Target gains the salt-rimed (level 1) condition for 1 scene. Drowned Church witnesses recognize the mark on sight; Bell Court does not. The mark is invisible to most NPCs; visible to anyone with Drowned Church Faith Meter >= 4."},{"spell_id":"unrecord","name":"Unrecord","level":3,"school":"regional","regional_school_id":"greywake_imposed","regional_origin_id":"greywake","regional_pantheon_alignment":"greywake_drowned_church_config","casting_time":"1 action","range":"30 ft","components":{"v":true,"s":true,"m":true,"m_text":"a vial of unrecorded ink (consumed)","m_consumed":true,"m_cost_gp":35},"duration":{"kind":"permanent"},"concentration":false,"ritual_eligible":false,"save_type":"wis","attack_kind":null,"damage_dice":null,"damage_type":null,"classes_allowed":["warlock","wizard"],"domain_aligned":[],"cost_layer":{"fatigue":2,"notice":1,"corruption":0,"authority":1,"ruin":1,"creation":0,"scaling_rule":"L3: as listed. Upcast L4+: may target larger events (severity threshold +1 per slot level above 3); notice scaling +1 per slot above L4."},"description_template":"Caster names a single witnessed event (must have occurred within the last 7 in-world days, severity <= 3). Target NPC (WIS save resists) loses memory of having witnessed that event. The event still occurred — canon ledger preserves it — but the target''s memory does not. If the target was the only witness, the event becomes contradiction-ledgered (kind: ''memory_vs_record''). Bell Court visitor ledger entries are not affected. State Manager commits the unrecord via state_diff with full validator chain."},{"spell_id":"compose","name":"Compose","level":4,"school":"regional","regional_school_id":"greywake_imposed","regional_origin_id":"greywake","regional_pantheon_alignment":"greywake_drowned_church_config","casting_time":"1 hour","range":"self","components":{"v":true,"s":true,"m":true,"m_text":"significance material commensurate with the object brought into canon (minimum 100 gp value or canon-event significance >= 3)","m_consumed":true,"m_cost_gp":100},"duration":{"kind":"permanent"},"concentration":false,"ritual_eligible":true,"save_type":null,"attack_kind":null,"damage_dice":null,"damage_type":null,"classes_allowed":["wizard","warlock"],"domain_aligned":[],"cost_layer":{"fatigue":2,"notice":2,"corruption":0,"authority":0,"ruin":0,"creation":2,"scaling_rule":"L4: brings one minor mundane object into canon (e.g., a key, a coin, a tool). Upcast L5+: significance and material cost scale linearly; L7+ allows minor uncommon-rarity items; L9 can bring a complete object including memory/witness payload. Creation cost +1 per slot above L4."},"description_template":"Over 1 hour of ritual, caster names a single object and brings it into canon by speaking its history three times. The object must be plausible for the region and the caster''s circumstance. State Manager validates plausibility and commits the object as a state_diff with the caster''s path_ledger crediting +2 path:creation. Witnesses within line of sight at the ritual conclusion may experience the object as ''remembered'' rather than ''created'' — this is the doctrinal preference of the Drowned Church. The composed object carries witness_payload from the significance material consumed."},{"spell_id":"harden_contradiction","name":"Harden Contradiction","level":5,"school":"regional","regional_school_id":"greywake_imposed","regional_origin_id":"greywake","regional_pantheon_alignment":"greywake_drowned_church_config","casting_time":"1 action","range":"60 ft","components":{"v":true,"s":true,"m":true,"m_text":"a copy of the record that is being contradicted (e.g., torn page from a ledger, fragment of a rumor written down)","m_consumed":true,"m_cost_gp":0},"duration":{"kind":"permanent"},"concentration":false,"ritual_eligible":false,"save_type":null,"attack_kind":null,"damage_dice":null,"damage_type":null,"classes_allowed":["warlock","wizard"],"domain_aligned":[],"cost_layer":{"fatigue":3,"notice":2,"corruption":0,"authority":1,"ruin":0,"creation":1,"scaling_rule":"L5: as listed. Upcast L6+ may resolve larger contradictions (severity threshold +1 per slot). At L7+, Corruption +1 begins to apply (the harder the contradiction, the more it scars the caster''s perception)."},"description_template":"Caster names an active contradiction in the canon ledger (a rumor vs canon, memory vs record, or unmade event entry). The contradiction is forced to resolve in the caster''s stated favor: one side becomes canonical, the other becomes contradiction-ledger preserved only. State Manager commits the resolution via state_diff with mandatory validator chain stage 5 (contradiction check) re-run. If the chosen resolution conflicts with a higher-severity canon-event committed by another actor (NPC, faction, deity-touched event), the spell fails and the caster takes the cost_layer regardless. Resolved contradictions cannot be re-opened by ordinary means; only canon-events of severity >= 4 may overturn them."}]'::jsonb) AS x
ON CONFLICT ("spell_id") DO NOTHING;
